/* ---------- utilidades ---------- */
const num = (n, dec = 1) =>
  n.toLocaleString("es-CO", { minimumFractionDigits: dec, maximumFractionDigits: dec });
const ent = (n) => n.toLocaleString("es-CO", { maximumFractionDigits: 0 });

const COLOR_ESTADO = { ok: C.verde, advertencia: C.ambar, inconsistente: C.rojo };
const TEXTO_ESTADO = { ok: "Cuadra", advertencia: "Revisar", inconsistente: "No cuadra" };

/* ============================================================
   Rodillo — el elemento firma.
   Reproduce los tambores del Fill-Rite: dígitos enteros en cajas
   claras y la décima en caja roja, igual que la carátula física.
   ============================================================ */
function Rodillo({ valor, enteros = 6, decima = null, alto = 44 }) {
  const digitos = String(Math.trunc(valor)).padStart(enteros, "0").split("");
  const ancho = Math.round(alto * 0.62);
  return (
    <div className="inline-flex items-stretch" style={{ gap: 2 }}>
      {digitos.map((d, i) => (
        <span
          key={i}
          className="flex items-center justify-center font-mono font-bold"
          style={{
            width: ancho, height: alto, fontSize: Math.round(alto * 0.56),
            color: "#101820",
            background: "linear-gradient(180deg,#F7F9FB 0%,#DFE6EC 45%,#FFFFFF 55%,#C9D3DC 100%)",
            borderRadius: 3, boxShadow: "inset 0 0 0 1px rgba(0,0,0,.35)",
          }}
        >
          {d}
        </span>
      ))}
      {decima !== null && (
        <span
          className="flex items-center justify-center font-mono font-bold"
          style={{
            width: ancho, height: alto, fontSize: Math.round(alto * 0.56),
            color: "#FFF3F1",
            background: "linear-gradient(180deg,#C0362B 0%,#9E2B22 45%,#D8483B 55%,#8C241C 100%)",
            borderRadius: 3, boxShadow: "inset 0 0 0 1px rgba(0,0,0,.4)",
          }}
        >
          {decima}
        </span>
      )}
    </div>
  );
}

