function Chip({ estado }) {
  const col = COLOR_ESTADO[estado];
  return (
    <span
      className="inline-flex items-center rounded-full font-semibold uppercase"
      style={{
        fontSize: 10, letterSpacing: "0.08em", padding: "3px 8px",
        color: col, background: col + "1F", border: "1px solid " + col + "55",
      }}
    >
      {TEXTO_ESTADO[estado]}
    </span>
  );
}

/* Zona A — el veredicto antes de los datos */
function ZonaA({ tono, titulo, frase, hechos, derecha }) {
  const col = tono === "alto" ? C.rojo : tono === "medio" ? C.ambar : C.verde;
  return (
    <div
      className="rounded-lg mb-5"
      style={{
        background: "linear-gradient(90deg," + col + "14 0%, " + C.panel + " 55%)",
        border: "1px solid " + C.lineaSuave, borderLeft: "3px solid " + col,
      }}
    >
      <div className="flex flex-col gap-5 p-5 md:flex-row md:items-start md:justify-between">
        <div style={{ maxWidth: 620 }}>
          <Eyebrow color={col}>{titulo}</Eyebrow>
          <p className="mt-2 font-semibold leading-snug" style={{ fontSize: 21, color: C.texto, letterSpacing: "-0.01em" }}>
            {frase}
          </p>
          <div className="mt-4 flex flex-wrap" style={{ gap: "18px 28px" }}>
            {hechos.map((h, i) => (
              <div key={i}>
                <div className="font-mono font-semibold" style={{ fontSize: 17, color: h.color || C.texto }}>
                  {h.valor}
                </div>
                <div style={{ fontSize: 11, color: C.suave, marginTop: 2 }}>{h.etiqueta}</div>
              </div>
            ))}
          </div>
        </div>
        {derecha && <div className="shrink-0">{derecha}</div>}
      </div>
    </div>
  );
}

