/* ====================== EXPORTACIÓN A EXCEL ======================
   Las columnas salen en el orden en que un auditor las revisa:
   identificación, las cuatro lecturas del medidor, el resultado, y al
   final el veredicto con su bandera. Los galones van como número, no
   como texto, para que el cliente pueda sumar sin limpiar la hoja.
   ================================================================ */
const FILA_CARGA = (c) => ({
  Fecha: c.fecha + " 2026",
  Hora: c.hora,
  Equipo: c.equipo,
  Descripción: c.desc,
  Conductor: c.conductor,
  "Tanda inicial (gal)": c.ti,
  "Totalizador inicial": c.toti,
  "Tanda final (gal)": c.tf,
  "Totalizador final": c.totf,
  "Galones despachados": c.gal,
  "Contador del equipo": c.contador,
  "Tipo de contador": c.tipo,
  Veredicto: TEXTO_ESTADO[c.estado],
  Banderas: c.banderas.join(", ") || "—",
  "Gal sin registrar": c.salto || "",
});

function anchos(hoja, medidas) {
  hoja["!cols"] = medidas.map((w) => ({ wch: w }));
  return hoja;
}

function descargarExcel(alcance) {
  const libro = XLSX.utils.book_new();
  const encabezado = [
    ["CUADRE · Control de combustible en planta"],
    ["Cliente", CLIENTE.nombre],
    ["Sede", CLIENTE.sede],
    ["Medidor", DISPENSADOR.medidor + " · instalado " + DISPENSADOR.instalado],
    ["Generado", "29 de julio de 2026, 09:30"],
    ["Alcance", alcance === "dia" ? "Detalle del día" : "Detalle del mes de julio de 2026"],
    ["Proveedor", "Lubryco S.A.S. — Buga, Valle del Cauca"],
    [],
    ["Nota", "Cifras de existencia estimadas a partir de remisiones. Margen esperado ±2%."],
  ];
  XLSX.utils.book_append_sheet(
    libro,
    anchos(XLSX.utils.aoa_to_sheet(encabezado), [14, 62]),
    "Portada"
  );

  const cargas = alcance === "dia" ? CARGAS.filter((c) => c.fecha === "29 jul") : CARGAS;
  XLSX.utils.book_append_sheet(
    libro,
    anchos(XLSX.utils.json_to_sheet(cargas.map(FILA_CARGA)),
      [12, 7, 9, 26, 18, 15, 16, 14, 16, 16, 18, 15, 12, 22, 15]),
    alcance === "dia" ? "Cargas del día" : "Detalle de cargas"
  );

  if (alcance === "mes") {
    XLSX.utils.book_append_sheet(
      libro,
      anchos(XLSX.utils.json_to_sheet(CONSUMO.map((c) => ({
        Fecha: c.d + " jul 2026",
        "Galones despachados": c.g,
        Observación: c.parcial ? "Día parcial, corte 09:30" : "",
      }))), [14, 20, 26]),
      "Consumo por día"
    );

    XLSX.utils.book_append_sheet(
      libro,
      anchos(XLSX.utils.json_to_sheet(EQUIPOS.map((e) => ({
        Equipo: e.cod,
        Descripción: e.desc,
        Categoría: e.cat,
        "Galones del período": e.gal,
        "Uso registrado": e.uso,
        Rendimiento: e.rend,
        "Desvío %": e.desvio,
      }))), [9, 26, 13, 19, 15, 14, 10]),
      "Consumo por equipo"
    );

    XLSX.utils.book_append_sheet(
      libro,
      anchos(XLSX.utils.json_to_sheet(ENTREGAS.map((e) => ({
        Remisión: e.rem,
        Fecha: e.fecha,
        "Galones entregados": e.gal,
        Carrotanque: e.placa,
        "Recibido por": e.recibe,
      }))), [12, 14, 18, 14, 18]),
      "Entregas Lubryco"
    );

    XLSX.utils.book_append_sheet(
      libro,
      anchos(XLSX.utils.aoa_to_sheet([
        ["Concepto", "Galones"],
        ["Entregado por Lubryco", BALANCE.entregado],
        ["Despachado a equipos", -BALANCE.despachado],
        ["Existencia estimada en tanque", BALANCE.existencia],
        [],
        ["Consumo promedio últimos 7 días", BALANCE.consumoDia],
        ["Autonomía estimada (días)", BALANCE.autonomia],
        ["Galones despachados sin equipo asignado", BALANCE.sinDueno],
      ]), [40, 12]),
      "Balance"
    );
  }

  const nombre =
    alcance === "dia"
      ? "Cuadre_El_Trebol_dia_2026-07-29.xlsx"
      : "Cuadre_El_Trebol_mes_2026-07.xlsx";
  XLSX.writeFile(libro, nombre);
}

