function Candado({ ok, texto, detalle }) {
  const col = ok ? C.verde : C.rojo;
  return (
    <div className="flex" style={{ gap: 10 }}>
      <span
        className="flex shrink-0 items-center justify-center font-bold"
        style={{ width: 17, height: 17, marginTop: 1, borderRadius: 4, background: col + "22", color: col, fontSize: 11, border: "1px solid " + col + "66" }}
      >
        {ok ? "✓" : "!"}
      </span>
      <div>
        <div style={{ fontSize: 12.5, color: C.texto, lineHeight: 1.4 }}>{texto}</div>
        <div style={{ fontSize: 11, color: C.suave, lineHeight: 1.5, marginTop: 2 }}>{detalle}</div>
      </div>
    </div>
  );
}

